// ranks-data.js - written by scripts/build-pages.ps1 from scripts/societies/. Do not edit. The Order the Ranks game:
// [slug, short name, of, for Kids mode, [[rank, its own word, level, why, line for children, picture, rank number]]], firm ranks only.
var GAME_RANKS = [
["ancient-egypt","New Kingdom Egypt","Ancient Egypt",1,[["The pharaoh","nesu (king), hem (Majesty), per-aa (pharaoh)",1,"The king stood apart from all other Egyptians.","The pharaoh was Egypt’s ruler, who led the army, made the laws and was honoured almost like a god.","/images/encyclopedia/thumbs/hatshepsut.jpg",1],["High officials","tjaty (vizier), ser (official), pat (the elite)",2,"Below the king stood the small circle of officials who ran his government, the elite that Egyptian texts called the pat.","Officials such as the vizier ran Egypt for the pharaoh, keeping its records and judging its court cases.","",2],["Farmers","ihwty (cultivators), nemhu (free private people)",7,"Most Egyptians were farmers living in mud-brick villages along the Nile.","Most Egyptians were farmers who grew wheat, barley and flax in fields watered by the Nile’s yearly flood.","",7],["Enslaved people","hem, bak (servants), sekeru-ankh (living captives)",8,"The wars of the New Kingdom made it Egypt’s great age of foreign slavery.","Enslaved people were owned by others and made to work without pay; many were prisoners taken in war.","",8]]],
["benin","Benin","the Kingdom of Benin",0,[["The Oba","Oba, Omo n'Oba",1,"The Oba was a sacred king.","The Oba was Benin’s king, and his people believed he was sacred.","/images/encyclopedia/thumbs/ozolua.jpg",1],["The Uzama","Uzama",2,"The Uzama were the senior hereditary chiefs of Benin, and their titles passed from father to son.","The Uzama were chiefs who inherited their titles and crowned each new Oba.","",2],["Palace chiefs","Eghaevbo n'Ogbe",3,"Oba Ewuare is credited with creating the palace chiefs, the Eghaevbo n’Ogbe, as one of two orders of chiefs appointed by the Oba and answerable to him.","Palace chiefs looked after the Oba’s treasures and household, and the Oba chose them himself.","",3],["Free villagers","",5,"Most of the Oba’s subjects were free farmers in the villages outside the capital, Edo-speaking in the heartland and of many other peoples in the conquered lands.","Most people in Benin were farmers who lived in villages led by their elders.","",6],["Enslaved people","",6,"Slavery was part of Benin’s order.","Enslaved people were owned by others and made to work without pay; many were captives from wars.","",7]]],
["kongo","Kongo","the Kingdom of Kongo",0,[["The king","mwene Kongo, manikongo",1,"The king of Kongo, the mwene Kongo or manikongo, was chosen for life by a small group of electors and senior officials from among the royal kin.","The king of Kongo ruled from the city of Mbanza Kongo and was chosen from the royal family.","/images/encyclopedia/thumbs/alvaro-i-of-kongo.jpg",1],["Royal kin and great nobles","mwissikongo; duque, marquês, conde",2,"The great nobles were the core of the mwissikongo, the ruling nobility of the capital: the royal kin, the electors and the governors of the great provinces, which had once been separate kingdoms.","Kongo’s great nobles governed its provinces, and some took Portuguese titles such as duke or count.","",2],["Lesser nobles and officials","mwene (mani); fidalgos",3,"A wider nobility of lesser lords and office-holders lived in the capital and the provincial towns.","Young nobles in Kongo went to royal schools and learned to read and write.","/images/encyclopedia/thumbs/mbanza-kongo.jpg",3],["Free villagers","",4,"Most people of Kongo were free villagers.","Most people in Kongo were farmers who lived in small villages and paid taxes to their lords.","",5],["Enslaved people","",5,"Slavery in Kongo was older than the Atlantic trade.","Enslaved people were owned by others and made to work without pay; many were captured in wars.","",6]]],
["athens","Athens","Classical Athens",1,[["Richest citizens","pentakosiomedimnoi (five-hundred-measure men)",1,"At the top stood the pentakosiomedimnoi, the “five-hundred-measure men”, whose land yielded at least 500 medimnoi of grain, oil or wine a year; Solon had defined the class in 594 BCE by wealth…","The richest Athenians were expected to pay for warships and for the plays at the city’s festivals.","/images/encyclopedia/thumbs/pericles.jpg",1],["Knights","hippeis (horsemen)",2,"The hippeis, or knights, were the second class: men whose land yielded at least 300 medimnoi a year, enough, in Aristotle’s account, to keep a horse.","Knights were rich Athenians who could afford a horse and rode in the city’s cavalry.","",2],["Hoplite class","zeugitai (yoked men)",3,"The zeugitai were the citizens whose land yielded at least 200 medimnoi a year.","Farmers of the hoplite class bought their own shields and spears and fought side by side.","/images/encyclopedia/thumbs/socrates.jpg",3],["Poorer citizens","thetes",4,"The thetes were the citizens whose land yielded less than 200 medimnoi a year, or who had none: smallholders, craftsmen, shopkeepers and labourers in the city and the port of Piraeus.","Poorer citizen men could vote in the Assembly, serve on juries and row the city’s warships.","",4],["Metics","metoikoi (resident foreigners)",5,"Metics were free people who lived in Athens without being citizens: Greeks from other cities drawn by its trade and wealth, some non-Greeks, and freed slaves.","Metics were free people from other places who lived and worked in Athens but could not vote.","/images/encyclopedia/thumbs/aristotle.jpg",5],["Enslaved people","douloi, andrapoda; demosioi (public slaves)",6,"Slaves did much of the work of Attica.","Enslaved people were owned by others and made to work without pay; some were later freed.","",6]]],
["ancient-rome","Rome","Ancient Rome",1,[["The emperor","princeps, imperator, Augustus",1,"The emperor was in name the “first citizen” (princeps) and in fact the master of the state.","The emperor commanded the army, made the laws and had his face on the coins.","/images/encyclopedia/thumbs/trajan.jpg",1],["Senators","ordo senatorius",2,"The senatorial order stood highest.","Senators were rich landowners who advised the emperor and governed the provinces.","/images/encyclopedia/thumbs/roman-senate.jpg",2],["Equestrians","ordo equester, equites",3,"The equestrians, or knights, formed the second order.","Equestrians, or knights, were wealthy men who ran the emperor’s offices, money and some of his armies.","/images/encyclopedia/thumbs/pliny-the-elder.jpg",3],["Town councillors","decuriones, ordo decurionum",4,"Every Roman town had a council of decurions, drawn from the leading local families and bound by a property qualification that each town set for itself.","Every Roman town had a council of rich local men who ran its markets, temples and festivals.","",4],["Free people","plebs, peregrini (free non-citizens), humiliores",6,"Most of the empire’s free people were small farmers, tenants, labourers, craftsmen and shopkeepers.","Most Romans were farmers, craftspeople and shopkeepers who worked hard to feed their families.","/images/encyclopedia/thumbs/latifundium.jpg",6],["Freed slaves","liberti, libertini",7,"A slave freed by a Roman citizen became a citizen, something Greek observers found remarkable, but not an equal one.","Enslaved people who were set free became Roman citizens, and their children were born free.","",7],["Enslaved people","servi",8,"Enslaved people were property.","Enslaved people were owned by others and made to work without pay; some were later set free.","",8]]],
["vikings","Vikings","the Vikings",1,[["Kings","konungr",1,"Kingship in Scandinavia began small: around 800 Norway alone had some 30 petty kingdoms, and kings’ names are reliably known only for the later Viking Age.","Viking kings led armies and fleets, gave gifts to their warriors and in time made their people Christian.","/images/encyclopedia/thumbs/harald-bluetooth.jpg",1],["Jarls","jarl",2,"A jarl (earl) was the greatest lord below a king.","Jarls were powerful lords, one step below the king, who owned great farms and ruled whole regions.","",2],["Chieftains","hersir, goði, höfðingi",3,"Below the jarls stood the chieftains of districts, wealthy landowners who led their neighbours in war and law.","Chieftains led the farmers of their district in war and at the assemblies where laws were made.","",3],["Free farmers","bóndi (pl. bœndr), karl",5,"Most free Scandinavians were farmers (bœndr), the karlar of Rígsþula, who worked their own land with their households.","Most Vikings were farmers, not raiders: they grew grain, kept animals and met at assemblies to make laws.","",5],["Freed slaves","leysingi (pl. leysingjar)",6,"A thrall could be freed by the owner, in the owner’s will, or by buying freedom with money earned; according to the sagas the Norwegian magnate Erling Skjalgsson set each of his thralls a price and…","Some thralls were set free, and some were even given land to farm by their former owners.","",6],["Thralls","þræll, ambátt",7,"Thralls were property: they could be bought, sold and punished, and the 12th-century Gulating law made anyone who harmed a thrall pay the owner, as for damage to cattle.","Thralls were enslaved people, often captured in raids, who were owned by others and made to work without pay.","",7]]],
["byzantine-empire","Byzantium","the Byzantine Empire",0,[["The emperor","basileus, autokrator",1,"The emperor (basileus) was held to be chosen by God and to be the living law (nomos empsychos), and his court, whose ceremonies Constantine VII had set down in the Book of Ceremonies, was meant to…","The emperor ruled from a great palace in Constantinople, and people believed God had chosen him.","/images/encyclopedia/thumbs/constantine-vii.jpg",1],["The powerful","dynatoi, archontes",2,"At the top of society stood “the powerful” (dynatoi), a legal term for the senior ranks of civil, military and church office, who usually also owned great estates.","Rich families held the top jobs in the army and government, but they needed the emperor’s favour.","/images/encyclopedia/thumbs/bardas-skleros.jpg",2],["Officials","logothetai, asekretis, notarioi",3,"The empire was governed by a large, literate bureaucracy: in Constantinople there were hundreds, if not thousands, of officials at any time.","Officials kept the records, collected taxes and ran the empire’s offices for the emperor.","",4],["Free peasants","penetes, georgoi",6,"Most Byzantines were peasants, and in the 10th century free smallholders, who owned their land and lived in village communities, were the main pillar of society and of the state’s revenue.","Many farmers owned small fields in villages and paid taxes to the emperor.","",8],["Dependent peasants","paroikoi",7,"Paroikoi were peasants who farmed land they did not own, as tenants on the estates of great landowners, monasteries, churches and the emperor himself.","Many farmers worked land that belonged to rich landowners or monasteries and paid them rent.","",9],["Enslaved people","douloi",8,"Slavery remained legal throughout Byzantine history and reached its height in the 10th century, when wars in the Balkans and the reconquest of Crete in 961 brought many captives, and Rus’ traders…","Enslaved people were owned by others and made to work without pay, mostly as servants in rich homes.","",10]]],
["feudal-europe","Feudal Europe","Feudal Europe",1,[["The king","rex, roi, König, imperator",1,"Kings were anointed with holy oil at their coronation, which set them apart from every lord, and they were expected to defend the Church, keep the peace and do justice.","Kings were crowned in church and ruled with the help of great lords, who promised to be loyal to them.","/images/encyclopedia/thumbs/henry-ii-of-england.jpg",1],["Great lords","duces, comites, barones, magnates",2,"The great lords were the dukes, counts and barons who held whole provinces or clusters of manors, often directly from the king.","Great lords such as dukes and counts lived in castles, ruled large lands and led knights for the king.","/images/encyclopedia/thumbs/henry-the-lion.jpg",2],["Knights","milites, chevaliers, Ritter, ministeriales",3,"Knights were mounted warriors in mail armour, the elite of every army.","Knights were warriors who fought on horseback and were given land in return for serving their lord.","/images/encyclopedia/thumbs/wolfram-von-eschenbach.jpg",4],["Townspeople","burgenses, bourgeois, Bürger",5,"Walled towns grew fast from the 11th century, and their people did not fit the three orders.","Townspeople were merchants and craftspeople, and many towns won the right to run their own markets and councils.","",6],["Serfs and villeins","servi, villani, nativi, bordarii",6,"Most peasants were dependent tenants of a lord, and many were serfs, legally unfree, whose children inherited their status.","Serfs were farmers who had to work on their lord’s land and could not move away without his permission.","/images/encyclopedia/thumbs/villein.jpg",9],["Enslaved people","servi, theows",7,"At the start of the period slavery still existed.","Enslaved people were owned by others and worked without pay; in England slavery had died out by about 1150.","",10]]],
["ancien-regime-france","Ancien Régime France","Ancien Régime France",0,[["The king","roi, Roi Très Chrétien",1,"The king stood outside and above the three orders.","The king lived in the great palace of Versailles and was crowned in the cathedral of Reims.","/images/encyclopedia/thumbs/louis-xv.jpg",1],["Bishops and abbots","haut clergé, prélats",2,"The clergy formed the First Estate, the senior order, and its leaders lived as great lords.","Bishops were powerful churchmen from noble families, and the church they led owned rich lands.","/images/encyclopedia/thumbs/charles-maurice-de-talleyrand.jpg",2],["The bourgeoisie","bourgeoisie, bourgeois",4,"At the top of the Third Estate stood the bourgeoisie: merchants and bankers, financiers and tax farmers, lawyers, notaries and doctors, the holders of venal offices, and rentiers living on their…","The bourgeois were well-off townspeople, such as merchants, bankers and lawyers.","/images/encyclopedia/thumbs/voltaire.jpg",5],["Artisans and workers of the towns","maîtres, compagnons, apprentis, menu peuple",5,"About a fifth of the French lived in towns, and Paris alone had 600,000 to 650,000 people.","Craftspeople in towns belonged to guilds, groups that set the rules for each trade, such as baking.","",6],["Serfs","mainmortables, serfs",6,"Serfdom had faded from most of France long before the 18th century, but it survived in pockets of the east and centre, above all on the lands of churches and abbeys in Franche-Comté, Burgundy, Berry…","A few French farmers were still serfs in 1789 and had fewer rights than their neighbours.","",8],["Enslaved people","esclaves",7,"Slavery had no place in the law of France itself: the soil of France was held to make free, and enslaved people brought from the colonies fled or sued for their freedom, and some French courts…","Enslaved people were owned by others and made to work without pay on plantations in France’s colonies.","",9]]],
["russian-empire","Russian Empire","the Russian Empire",0,[["The emperor","imperator, tsar, samoderzhets",1,"The emperor was an autocrat: no assembly shared his power, and titles, ranks and privileges were his to grant.","The emperor, or tsar, ruled Russia alone, with no parliament to share his power.","/images/encyclopedia/thumbs/alexander-i-of-russia.jpg",1],["Nobles","dvoryanstvo, potomstvennye dvoryane, lichnye dvoryane",2,"The nobility (dvoryanstvo) was the first estate.","Many nobles owned large country estates and the serfs who farmed them.","/images/encyclopedia/thumbs/alexander-pushkin.jpg",2],["Merchants","kupechestvo, kuptsy",4,"The merchants (kupechestvo) were enrolled in three guilds according to the capital they declared, under Catherine II’s rules of 1775, each guild with its own trading rights.","Merchants were traders who paid to join a merchant guild, which gave them the right to trade.","",4],["Townspeople","meshchane, tsekhovye",5,"The meshchane were the lower urban estate, ranked above the peasants and below the merchant guilds: small traders, artisans, shopkeepers and urban workers who were registered in a town but could not…","Townspeople ran small shops and workshops in Russia’s towns and paid taxes to the government.","",5],["State and crown peasants","gosudarstvennye krestyane, udelnye krestyane",6,"About as many peasants lived on the land of the state as on private estates.","State peasants farmed land that belonged to the government, and unlike serfs they could not be sold.","",8],["Serfs","krepostnye krestyane, pomeshchichi krestyane",7,"Serfs were peasants owned, with the land they lived on, by noble landlords, and bound to it since the Law Code of 1649.","Serfs were farmers who belonged to a landowner and were not allowed to leave his estate.","",9]]],
["mamluk-sultanate","Mamluk Sultanate","the Mamluk Sultanate",0,[["The sultan","sultan, al-malik",1,"The sultan ruled Egypt, Syria and the Hejaz from the Citadel of Cairo.","Many Mamluk sultans had been bought as slave boys and trained as soldiers before they rose to the throne.","/images/encyclopedia/thumbs/baybars.jpg",1],["Amirs","amir; amir mi'a (of a hundred), amir tablkhana (of forty), amir 'ashara (of ten)",2,"The amirs were the senior mamluks, the commanders and governors of the realm.","Amirs were the top army commanders, paid with the taxes from lands the sultan assigned to them.","",2],["Mamluk soldiers","mamluk (pl. mamalik), al-mamalik al-sultaniyya (the royal mamluks)",3,"The mamluks were the free soldiers of the ruling caste, men who had begun life as slaves.","Mamluks were boys bought as slaves and trained as soldiers, then set free to serve their masters in the army.","/images/encyclopedia/thumbs/mamluk.jpg",3],["Peasants","fallahin (sing. fallah)",7,"Most of the sultanate’s people were peasants: the fellahin of the Nile valley and Delta and the villagers of Syria and Palestine.","Most people were farmers, and in Egypt their fields were watered by the Nile’s yearly flood.","",8],["Enslaved people","ʿabd (slave), jariya (slave woman), umm walad, tawashi (eunuch)",8,"Apart from the boys bought to become mamluks, slaves in the sultanate served mostly in households, and women always outnumbered men among them.","Enslaved people were owned by others and made to work without pay, most of them as household servants.","",10]]],
["ottoman-empire","Ottoman Empire","the Ottoman Empire",0,[["The sultan","sultan, padişah",1,"The sultan, the padişah or “lord of kings”, was the source of every office and, in law, the owner of the empire’s farmland.","The Ottoman sultan ruled from Topkapı Palace in Istanbul and could appoint or dismiss any official.","/images/encyclopedia/thumbs/mehmed-ii.jpg",1],["Viziers, governors and palace officers","vezir, paşa, beylerbeyi, sancakbeyi, kul",2,"At the top of the ruling class stood the grand vizier, the sultan’s deputy, with the other viziers of the imperial council (divan), the governors-general of the provinces (beylerbeyi), eight in 1527…","Many Ottoman viziers and governors had been taken from Christian families as boys and trained in the sultan’s palace.","/images/encyclopedia/thumbs/pargali-ibrahim-pasha.jpg",2],["Merchants and guild craftsmen","tüccar, esnaf",5,"The townspeople were reaya, taxpayers, but the sultans needed them.","Ottoman craftsmen belonged to guilds that set standards for their trades and helped members in hard times.","",6],["Enslaved people","köle, cariye, esir",6,"Islamic law forbade enslaving Muslims or the empire’s own Christian and Jewish subjects, so the enslaved were outsiders: prisoners of war, people seized by Barbary corsairs, Africans brought across…","Enslaved people were owned by others and made to work without pay; many were later set free.","",9]]],
["han-china","Han China","Han China",1,[["The emperor","huangdi, tianzi",1,"The emperor (huangdi), the Son of Heaven (tianzi), was always a man of the Liu family descended from the founder, Liu Bang.","The Han emperor was called the Son of Heaven, and people were not allowed to say his name.","/images/encyclopedia/thumbs/liu-bang.jpg",1],["Kings and marquesses","zhuhou wang, liehou",2,"Below the emperor stood the kings, his brothers, uncles, nephews and sons other than the heir.","Han kings were usually relatives of the emperor, and they lived on taxes from the lands they were given.","/images/encyclopedia/thumbs/han-xin.jpg",2],["Officials and scholars","guan, shi",3,"Those who served in government held a privileged place just below the nobles.","Many Han officials studied the books of Confucius and were chosen for being good sons and honest men.","/images/encyclopedia/thumbs/xiao-he.jpg",3],["Farmers","nong",5,"Farmers were the great majority and, in Confucian eyes, the “root” of the state, second only to scholars.","Most people in Han China were farmers, and men had to work for the government for one month each year.","",5],["Artisans","gong",6,"Artisans stood between farmers and merchants in the Confucian order.","Han craftspeople made shiny lacquer cups, bronze mirrors and fine silk cloth.","",6],["Enslaved people","nubi",8,"Slaves (nubi) were few, perhaps one person in a hundred, far fewer than in the Roman world.","Enslaved people were owned by others and made to work without pay; in Han China there were few of them.","",8]]],
["song-china","Song China","Song China",0,[["The emperor","huangdi, tianzi",1,"The emperor (huangdi), the Son of Heaven (tianzi), was always a man of the Zhao family.","The Song emperor was called the Son of Heaven, and he chose the officials who ran the empire.","/images/encyclopedia/thumbs/emperor-taizu-of-song.jpg",1],["Scholar-officials","shidafu, guanhu (official households)",3,"The scholar-officials (shidafu) governed the empire, and their households formed the privileged “official households” (guanhu), largely spared labour service.","Most Song officials got their jobs by passing very hard written exams.","/images/encyclopedia/thumbs/wang-anshi.jpg",3],["Landowning farmers","nong (farmers), zhuhu (main households)",5,"Most Song people were farm families who owned some land, and in 1034 four households in five were rural.","Most people in Song China were farmers, and in the warm south many grew two crops of rice a year.","",5],["Bondservants and slaves","nubi (slaves), jianmin (\"mean people\")",10,"At the bottom stood the “mean people” (jianmin), whom the law, largely inherited from the Tang code, ranked below all commoners.","Enslaved people and bound servants had to work for rich families, but there were fewer slaves than in earlier times.","",10]]],
["yuan-china","Yuan China","Yuan China",0,[["The emperor (Great Khan)","huangdi, khagan (qa'an)",1,"The Yuan ruler was at once emperor (huangdi) to his Chinese subjects and khagan, Great Khan, to the Mongols.","The Yuan ruler was called the Great Khan by the Mongols and the emperor by the Chinese.","/images/encyclopedia/thumbs/kublai-khan.jpg",1],["Mongol princes and imperial in-laws","wang (princes), küregen (imperial sons-in-law)",2,"Below the emperor stood the Golden Lineage, the princes descended from Genghis Khan, and the families that married into it.","Mongol princes were relatives of the emperor who lived on the taxes of lands given to them.","/images/encyclopedia/thumbs/kurultai.jpg",2],["Officials","guan (officials), darughachi (overseers)",3,"The Yuan kept the institutions of a Chinese state, a Central Secretariat, a Bureau of Military Affairs and a Censorate, but filled the posts by origin.","Yuan officials ran the government, and the very top jobs were kept for Mongols and peoples from Central and West Asia.","",3],["Northern Chinese","Han ren",8,"The third category, the Han ren, took in the subjects of the former Jin state in the north: northern Chinese, together with Khitans, Jurchens and Koreans.","Northern Chinese farmers ranked above the southern Chinese under Mongol rule.","/images/encyclopedia/thumbs/khitans.jpg",8],["Southern Chinese","nanren (\"southerners\"), manzi",9,"The southerners (nanren), the subjects of the Southern Song conquered in the 1270s, were by far the largest group and the lowest of the four, because they had resisted longest.","Southern Chinese were the biggest group in Yuan China but the least favoured by its Mongol rulers.","",9],["Enslaved people","qukou (\"driven people\"), nubi",10,"The Mongol conquests enslaved great numbers of people.","Enslaved people were owned by others and made to work without pay; many had been captured in wars.","",10]]],
["joseon","Joseon Korea","Joseon Korea",0,[["The king","wang, imgeum",1,"The king (wang) stood at the head of the state and of its Confucian order.","Joseon kings ruled with the help of scholar-officials, and King Sejong gave Korea its own alphabet, hangul.","/images/encyclopedia/thumbs/taejo-of-joseon.jpg",1],["Yangban","yangban (munban, civil; muban, military), sadaebu",2,"The yangban, the “two orders” of civil (munban) and military (muban) officials, were the ruling class.","Yangban were Korea’s ruling families, whose sons studied for years to pass the government exams.","",2],["Middle people","jungin (chungin), hyangni (local clerks), seoeol (sons of concubines)",3,"Between the yangban and the commoners stood the jungin, the “middle people”: the hereditary technical specialists of the government and their families.","The “middle people” were Korea’s interpreters, doctors and clerks, who passed their own special exams.","/images/encyclopedia/thumbs/kim-hong-do.jpg",3],["Commoners","sangmin, yangin (\"good people\")",4,"Most Koreans were commoners (sangmin), the free “good people” (yangin) of the law: farmers above all, with artisans, merchants and fishermen.","Most Koreans were farmers, and by law ordinary people had to wear plain white clothes.","",4],["Enslaved people","nobi; gongnobi (state-owned), sanobi (privately owned)",5,"The nobi were the core of the lowborn (cheonmin), and in the 15th to 17th centuries, the system’s height, they made up at least 30 per cent of the people.","Enslaved people, called nobi, were owned by others and had to work for them; their children were born enslaved too.","",5]]],
["tokugawa-japan","Tokugawa Japan","Tokugawa Japan",1,[["Daimyo","daimyō",3,"Below the shogun stood the daimyo, the lords of about 260 to 270 domains (han), each assessed at 10,000 koku of rice or more; the greatest, the Maeda of Kaga, held about a million.","Daimyo were great lords who ruled parts of Japan for the shogun and had to live in his city every other year.","/images/encyclopedia/thumbs/date-masamune.jpg",3],["Samurai","bushi, samurai",4,"The samurai were the hereditary warrior class, perhaps 400,000 men.","Samurai were warriors who wore two swords, and in the long Edo peace most of them worked as officials and guards.","/images/encyclopedia/thumbs/bushido.jpg",4],["Peasants","hyakushō",6,"Four people in five were peasants (hyakushō), the villagers who grew the rice on which the whole order rested.","Most people in Edo Japan were farmers who grew rice and paid a large share of it to their lord.","/images/encyclopedia/thumbs/ninomiya-sontoku.jpg",6],["Kawata outcasts","kawata, eta (the official term, now a slur)",7,"The kawata, called eta in official documents (a term now a slur), were hereditary outcasts.","Kawata families did jobs such as leatherwork that others thought unclean, and they were made to live apart.","",9]]],
["classical-india","Classical India","Classical India",0,[["The king","rājan, mahārājādhirāja",1,"The law books made kingship the duty of a Kshatriya: to protect his subjects, punish wrongdoers and uphold the order of the varnas, in return for a share of the harvest, traditionally a sixth.","Indian kings took part of every harvest as tax and were expected to protect their people.","/images/encyclopedia/thumbs/samudragupta.jpg",1],["Vaishyas","vaiśya, śreṣṭhin, sārthavāha",4,"The Vaishyas were the third varna and, like the two above them, twice-born, entitled to study the Vedas.","Vaishyas were traders, bankers and farmers, and many of them belonged to guilds.","",5],["Shudras","śūdra",5,"The Shudras were the fourth varna, born, the law books said, to serve the three twice-born varnas.","Shudras were farmers, workers and craftspeople, and old law books said they should serve the higher groups.","",6],["Chandalas and other outcastes","caṇḍāla, śvapaca",6,"Below and outside the four varnas the texts placed groups they held to be impure, above all the Chandalas, along with the Shvapachas and peoples such as the Nishadas.","Chandalas were made to live apart from others and did work such as carrying away the dead.","",7]]],
["mughal-empire","Mughal India","the Mughal Empire",0,[["The emperor","pādshāh",1,"The emperor, the pādshāh, was the source of every rank.","The Mughal emperor gave every noble his rank, and when he died his sons often fought each other for the throne.","/images/encyclopedia/thumbs/akbar.jpg",1],["Ranked nobles and officers","mansabdār, umarā",2,"Under the mansabdari system every officer of the empire above the lowest levels, judges apart, held a mansab, a numbered rank in one service that was army, nobility and civil government at once.","Mughal nobles held numbered ranks that showed how many horsemen they had to keep ready for the emperor.","/images/encyclopedia/thumbs/man-singh-i.jpg",2],["Artisans and townspeople","",5,"Mughal India had many large towns: under Akbar, Nizamuddin Ahmad counted 120 great cities and 3,200 townships, and Agra, Lahore and Delhi may each have held several hundred thousand people.","Mughal weavers made fine cotton cloth, such as muslin, that people bought all over Asia and Europe.","",6],["The lowest castes","",6,"Below the peasants stood the castes that Brahmin texts placed outside the four varnas altogether and that higher castes treated as untouchable, because their hereditary work, such as tanning hides…","People of the lowest castes were kept apart by higher castes and did work such as tanning leather and sweeping.","",8]]],
["classic-maya","Classic Maya","the Classic Maya",0,[["Holy lords and overlords","k'uhul ajaw (\"holy lord\"), kaloomte' (overlord)",1,"Each kingdom was ruled by a holy lord, the k’uhul ajaw, who stood between his people and the gods.","Each Maya kingdom had a “holy lord”, a king who led its rituals and its wars.","/images/encyclopedia/thumbs/kinich-janaab-pakal.jpg",1],["Nobles","ajaw (\"lord\"), sajal (\"feared one\", a subordinate lord), ch'ok (\"youth\", a young noble)",2,"Below the kings stood a hereditary nobility of royal kin and great families.","Maya nobles lived in stone houses near the centre of their city, wore jade and served at the king’s court.","",2],["Commoners","",3,"The great majority were commoners: farmers, labourers and servants, and also craftsmen and a few minor officials.","Most Maya were farmers who grew maize, beans and squash and lived in houses with thatched roofs.","",5],["Captives and the enslaved","baak (\"captive\")",4,"Warfare filled the lowest rank with captives.","Prisoners taken in war were made to work for their captors, and some were sacrificed to the gods.","",6]]],
["aztec-empire","Aztecs","the Aztec Empire",1,[["The huey tlatoani","huey tlatoani (\"great speaker\")",1,"At the top stood the huey tlatoani, the “great speaker”.","The huey tlatoani, or “great speaker”, ruled the Aztecs from the island city of Tenochtitlan.","/images/encyclopedia/thumbs/huey-tlatoani.jpg",1],["Nobles","pipiltin, teteuctin (lords)",2,"The nobles (pipiltin) were born to their rank and claimed descent from the Toltecs and, through them, from the god Quetzalcoatl.","Aztec nobles were born into their rank, went to temple schools and became generals, officials and priests.","/images/encyclopedia/thumbs/tlacaelel.jpg",2],["Commoners","macehualtin",5,"Most people were commoners (macehualtin), organised in calpolli: wards or villages of related families, each with its own leader, temple and school.","Most Aztecs were farmers who grew maize, beans and squash and gave part of what they made to their rulers.","/images/encyclopedia/thumbs/macehualtin.jpg",5],["Enslaved people","tlacotin (sing. tlacotli)",7,"Enslaved people (tlacotin) were owned by others, but Aztec slavery was not inherited: the children of slaves were born free.","Enslaved people had to work for an owner without pay, but their children were born free.","",7]]],
["saint-domingue","Saint-Domingue","Saint-Domingue",0,[["The governor-general and the intendant","gouverneur général, intendant",1,"Saint-Domingue, the richest colony of the French crown, was governed for the king by two officials sent from France.","A governor and an intendant sent from France ran Saint-Domingue for the king.","/images/encyclopedia/thumbs/saint-domingue.jpg",1],["Great planters and merchants","grands blancs",2,"At the top of colonial society stood the grands blancs, the “big whites”: the owners of the great sugar estates, the leading merchants of Cap-Français and Port-au-Prince, and the senior officials…","The richest white planters owned huge sugar farms, and many of them lived far away in France.","",2],["Poorer whites","petits blancs",3,"Most whites were petits blancs, “little whites”: overseers and managers on the plantations, artisans, shopkeepers, clerks, sailors, soldiers, slave dealers and day labourers, along with small…","Poorer white people worked as overseers, craftsmen and shopkeepers, and many of them died of fevers.","",3],["Free people of colour","gens de couleur libres, affranchis",4,"Saint-Domingue had the largest and richest free population of colour in the Caribbean.","Free people of colour could own farms and businesses, but unfair laws kept them out of many jobs.","/images/encyclopedia/thumbs/toussaint-louverture.jpg",4],["Enslaved field workers","esclaves de jardin; bossales (born in Africa)",6,"The great majority of Saint-Domingue’s people were enslaved field workers, and about two-thirds of them had been born in Africa.","Most people in Saint-Domingue were enslaved and forced to work on sugar and coffee farms without pay.","",6]]],
["hawaii","Hawaii","Hawaii under the kapu",0,[["The paramount chief","aliʻi nui, mōʻī",1,"Each island kingdom had its paramount chief (aliʻi nui), the greatest of the chiefs in power, if not always in birth.","Kamehameha I was a great chief who united the Hawaiian Islands and became their first king.","/images/encyclopedia/thumbs/kalaniopuu.jpg",1],["High chiefs","aliʻi, aliʻi ʻaimoku (district chiefs), nīʻaupiʻo (the highest grade)",2,"The chiefs (aliʻi) traced their descent from the gods, and a chief’s rank depended on the genealogy of both parents.","High chiefs wore cloaks made from many thousands of tiny red and yellow bird feathers.","",2],["Commoners","makaʻāinana",4,"Most Hawaiians were commoners (makaʻāinana), who farmed, fished and practised the simpler crafts.","Most Hawaiians were farmers and fishers who grew taro, caught fish and gave part of their food to the chiefs.","",5],["Kauwā outcasts","kauwā",5,"At the bottom stood the kauwā, a hereditary group set apart from every other class and despised by it.","The kauwā were outcasts: other Hawaiians were forbidden to marry them, and they worked for the chiefs.","",6]]]
];
